50	// validateStrictText rejects invalid UTF-8 anywhere in a Go-constructed
51	// config, in a fixed order independent of map iteration: app, revision,
52	// image, spreadBy, then every candidate (ID before its tags, tags in
53	// ascending key order), then every include and exclude condition in list
54	// order (entries likewise in ascending key order). The input is only read.
55	func validateStrictText(in ReleasePlanInput) error {
56		if !utf8.ValidString(in.App) {
57			return &invalidConfigTextError{where: `字段 "app"`}
58		}
59		if !utf8.ValidString(in.Revision) {
60			return &invalidConfigTextError{where: `字段 "revision"`}
61		}
62		if !utf8.ValidString(in.Image) {
63			return &invalidConfigTextError{where: `字段 "image"`}
64		}
65		if !utf8.ValidString(in.SpreadBy) {
66			return &invalidConfigTextError{where: `字段 "spreadBy"`}
67		}
68		for i, c := range in.Clusters {
69			if !utf8.ValidString(c.ID) {
70				return &invalidConfigTextError{where: fmt.Sprintf(`clusters[%d] 的字段 "id"`, i)}
71			}
72			if err := validateStrictTagText(i, c.Tags); err != nil {
73				return err
74			}
75		}
76		if err := validateStrictConditionText("include", in.Include); err != nil {
77			return err
78		}
79		if err := validateStrictConditionText("exclude", in.Exclude); err != nil {
80			return err
81		}
82		return nil
83	}
