86	// candidate position. Entries are examined in ascending key order; for each
87	// entry the key is checked before its value. An invalid value is reported
88	// with the (valid) key it belongs to; an invalid key is quoted byte-for-byte
89	// (so the corrupt bytes are shown as Go-escaped octets rather than rewritten
90	// to "�") and reported as belonging to that candidate's tags object.
91	func validateStrictTagText(clusterIndex int, tags map[string]string) error {
92		for _, k := range sortedLabelKeys(tags) {
93			if !utf8.ValidString(k) {
94				return &invalidConfigTextError{
95					where: fmt.Sprintf("clusters[%d] 的标签映射包含非法键 %q", clusterIndex, k),
96				}
97			}
