100					where: fmt.Sprintf("clusters[%d] 的标签键 %q 对应的值", clusterIndex, k),
101				}
102			}
103		}
104		return nil
105	}
106	
107	// validateStrictConditionText checks every condition of one field
108	// ("include" or "exclude") at its zero-based list position, applying the
109	// same ascending-key, key-before-value order as
110	// validateStrictTagText.
111	func validateStrictConditionText(field string, conds []LabelCondition) error {
112		for i, cond := range conds {
113			for _, k := range sortedLabelKeys(cond) {
