package darksafe

import (
	"fmt"
	"unicode/utf8"
)

// This file extends the strict-text rule (see stricttext.go for the JSON
// entry) to a release configuration constructed directly in Go memory and
// handed to ValidateReleaseInput or MakeReleasePlan.
//
// A Go string can hold bytes that are not valid UTF-8. Without this check
// such bytes would survive into planning unchanged at first, but two
// distinct corrupt identities would be indistinguishable the moment the
// plan is written as JSON — encoding/json rewrites every invalid rune to
// the replacement character "�" (U+FFFD) — and corrupt tag keys or values
// would silently take part in label matching and fault-domain batching. The
// check therefore runs as the first stage of ValidateReleaseInput, before
// any business rule and hence before selection or batching: the config is
// rejected outright rather than producing a plan that looks successful.
//
// Legal text is used exactly as written — including Chinese, supplementary
// plane characters such as "😀", and a literally written "�" — and ordinary
// text that merely contains a backslash followed by "uD800" is not invalid
// UTF-8 (only the JSON entry deals with \uXXXX escapes at all).
//
// When several strings are invalid, exactly one deterministic problem is
// reported. Scalars are checked in their fixed field order; candidates and
// conditions at their real zero-based positions (disabled clusters and
// clusters that filtering would drop are checked just the same); within one
// tags object or condition the entries are examined in ascending key order,
// so map iteration order can never change the error. A value error names
// the key it belongs to; an invalid key names the tags object or condition
// object owning it.

// invalidConfigTextError reports a string in a directly constructed config
// that contains bytes which are not valid UTF-8. where is a field-and-
// position description in the same style as the business-validation errors:
// a top-level field for scalars, clusters[i] (plus the offending tag key or
// the owning tags object) for candidate data, and include[i]/exclude[i]
// (plus the condition key or owning condition object) for conditions.
type invalidConfigTextError struct {
	where string
}

func (e *invalidConfigTextError) Error() string {
	return fmt.Sprintf("内存配置包含无效 UTF-8 字节: %s", e.where)
}

// validateStrictText rejects invalid UTF-8 anywhere in a Go-constructed
// config, in a fixed order independent of map iteration: app, revision,
// image, spreadBy, then every candidate (ID before its tags, tags in
// ascending key order), then every include and exclude condition in list
// order (entries likewise in ascending key order). The input is only read.
func validateStrictText(in ReleasePlanInput) error {
	if !utf8.ValidString(in.App) {
		return &invalidConfigTextError{where: `字段 "app"`}
	}
	if !utf8.ValidString(in.Revision) {
		return &invalidConfigTextError{where: `字段 "revision"`}
	}
	if !utf8.ValidString(in.Image) {
		return &invalidConfigTextError{where: `字段 "image"`}
	}
	if !utf8.ValidString(in.SpreadBy) {
		return &invalidConfigTextError{where: `字段 "spreadBy"`}
	}
	for i, c := range in.Clusters {
		if !utf8.ValidString(c.ID) {
			return &invalidConfigTextError{where: fmt.Sprintf(`clusters[%d] 的字段 "id"`, i)}
		}
		if err := validateStrictTagText(i, c.Tags); err != nil {
			return err
		}
	}
	if err := validateStrictConditionText("include", in.Include); err != nil {
		return err
	}
	if err := validateStrictConditionText("exclude", in.Exclude); err != nil {
		return err
	}
	return nil
}

// validateStrictTagText checks one candidate's tags at its zero-based
// candidate position. Entries are examined in ascending key order; for each
// entry the key is checked before its value. An invalid value is reported
// with the (valid) key it belongs to; an invalid key is quoted byte-for-byte
// (so the corrupt bytes are shown as Go-escaped octets rather than rewritten
// to "�") and reported as belonging to that candidate's tags object.
func validateStrictTagText(clusterIndex int, tags map[string]string) error {
	for _, k := range sortedLabelKeys(tags) {
		if !utf8.ValidString(k) {
			return &invalidConfigTextError{
				where: fmt.Sprintf("clusters[%d] 的标签映射包含非法键 %q", clusterIndex, k),
			}
		}
		if !utf8.ValidString(tags[k]) {
			return &invalidConfigTextError{
				where: fmt.Sprintf("clusters[%d] 的标签键 %q 对应的值", clusterIndex, k),
			}
		}
	}
	return nil
}

// validateStrictConditionText checks every condition of one field
// ("include" or "exclude") at its zero-based list position, applying the
// same ascending-key, key-before-value order as
// validateStrictTagText.
func validateStrictConditionText(field string, conds []LabelCondition) error {
	for i, cond := range conds {
		for _, k := range sortedLabelKeys(cond) {
			if !utf8.ValidString(k) {
				return &invalidConfigTextError{
					where: fmt.Sprintf("%s[%d] 的条件对象包含非法键 %q", field, i, k),
				}
			}
			if !utf8.ValidString(cond[k]) {
				return &invalidConfigTextError{
					where: fmt.Sprintf("%s[%d] 的条件键 %q 对应的值", field, i, k),
				}
			}
		}
	}
	return nil
}

package darksafe

import (
	"errors"
	"fmt"
)

// This file holds the strict text check shared by every JSON string in a
// release configuration: member names and string values alike, in known
// fields and in unknown extra fields, however deeply nested.
//
// Go's encoding/json silently rewrites two kinds of corrupt text to the
// replacement character "�" (U+FFFD): invalid UTF-8 bytes inside a string,
// and \uXXXX escapes naming an unpaired surrogate (a high surrogate not
// immediately followed by a low-surrogate escape, or a low surrogate with no
// preceding high surrogate). Decoding through encoding/json alone would
// therefore turn two different original documents into the same cluster ID
// or tag value. This check rejects such documents before any decoded string
// is compared, so the rewrite can never feed identity comparison, label
// matching, or fault-domain batching.
//
// Legal text is untouched: valid UTF-8 (including a literally written "�",
// which is a legal character), \uXXXX escapes for BMP characters, and
// high+low surrogate pairs for non-BMP characters all decode to their
// intended strings. A backslash-escaped "D800" is ordinary text, not an
// escape sequence, and is accepted as such.
//
// The check is a policy over the shared structural walk (jsonwalk.go): the
// walker recognizes the nesting and reads the strings, and the text problems
// it surfaces — invalidUTF8Error and unpairedSurrogateError — are this
// check's verdicts. Anything structurally unexpected makes the walker stop
// (errUndecided) and defer to the encoding/json walk that follows, which
// reports the JSON format error with the established wording — so malformed
// documents keep their existing error messages.

// invalidUTF8Error reports a JSON string or member name containing bytes
// that are not valid UTF-8. For a member name, path points at the object
// owning the name; for a value, at the field or array item holding it.
type invalidUTF8Error struct {
	path  string
	isKey bool
}

func (e *invalidUTF8Error) Error() string {
	if e.isKey {
		return fmt.Sprintf("JSON 成员名包含无效 UTF-8 字节: 所属对象位置 %s", e.path)
	}
	return fmt.Sprintf("JSON 字符串包含无效 UTF-8 字节: 位置 %s", e.path)
}

// unpairedSurrogateError reports a \uXXXX escape naming one half of a
// surrogate pair without its mate: a high surrogate not immediately followed
// by a low-surrogate escape, or a low surrogate appearing on its own.
// escape is the offending escape spelling (e.g. `D800`); path and isKey
// locate it exactly as for invalidUTF8Error.
type unpairedSurrogateError struct {
	escape string
	path   string
	isKey  bool
}

func (e *unpairedSurrogateError) Error() string {
	if e.isKey {
		return fmt.Sprintf("JSON 成员名包含未配对的 Unicode 转义 %s: 所属对象位置 %s", e.escape, e.path)
	}
	return fmt.Sprintf("JSON 字符串包含未配对的 Unicode 转义 %s: 位置 %s", e.escape, e.path)
}

// checkStrictText scans the raw document and rejects any string — member
// name or value, anywhere in the structure — containing invalid UTF-8 bytes
// or an unpaired-surrogate \uXXXX escape. It runs before duplicate-member
// detection and business validation, so no rewritten string can be compared
// or planned with. A document the walker cannot structurally follow is left
// to the later encoding/json walk, which reports the format error.
func checkStrictText(data []byte) error {
	w := &jsonWalker{data: data}
	if err := w.walk(); err != nil && !errors.Is(err, errUndecided) {
		return err
	}
	return nil
}

