		App: "a", Revision: "r", Image: "i", BatchSize: 1,
		Clusters: []Cluster{
			{ID: "good", Tags: map[string]string{"env": "pr" + badUTF8 + "d"}},
			{ID: "bad" + badUTF8},
		},
