	lit := ReleasePlanInput{
		App: "a", Revision: "r", Image: "i", BatchSize: 1,
		Clusters: []Cluster{{ID: "x", Tags: map[string]string{"env": "�"}}},
		Include:  []LabelCondition{{"env": "�"}},
